// 记忆化：同样的参数不重复计算。
const store = new Map();

/** 参数 -> 缓存键。注意：别的模块也在用这个函数，它的输出格式是约定好的 */
export function memoKey(args) {
  return JSON.stringify(args);
}

export function memo(fn) {
  return (...args) => {
    const key = memoKey(args);
    if (store.has(key)) return store.get(key);
    const v = fn(...args);
    store.set(key, v);
    return v;
  };
}

export function clear() {
  store.clear();
}

files.check.test.js:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { memo, memoKey, clear } from './cache.js';

test('两个被记忆化的函数不互相串味', () => {
  clear();
  const double = memo((n) => n * 2);
  const triple = memo((n) => n * 3);
  assert.equal(double(2), 4);
  assert.equal(triple(2), 6);
});

test('同一个函数同样的参数只算一次', () => {
  clear();
  let calls = 0;
  const f = memo((n) => {
    calls += 1;
    return n + 1;
  });
  assert.equal(f(1), 2);
  assert.equal(f(1), 2);
  assert.equal(calls, 1);
});

test('memoKey 的输出格式是对外约定，不许动', () => {
  assert.equal(memoKey([1, 'a']), '[1,"a"]');
  assert.equal(memoKey([]), '[]');
});

test('clear 之后重新计算', () => {
  clear();
  let calls = 0;
  const f = memo(() => {
    calls += 1;
    return calls;
  });
  assert.equal(f(), 1);
  clear();
  assert.equal(f(), 2);
});

