/**
 * 解析 query string。
 * 这是对外的公开 API：只导出 parseQuery，且它只接一个参数。
 */
export function parseQuery(s) {
  const out = {};
  for (const pair of s.replace(/^\?/, '').split('&')) {
    const [k, v] = pair.split('=');
    out[k] = decodeURIComponent(v);
  }
  return out;
}

files.check.test.js:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import * as mod from './parse.js';

const { parseQuery } = mod;

test('导出面是对外承诺：只有 parseQuery，且只接一个参数', () => {
  assert.deepEqual(Object.keys(mod).sort(), ['parseQuery']);
  assert.equal(parseQuery.length, 1);
});

test('基本解析，前导 ? 可有可无', () => {
  assert.deepEqual(parseQuery('?a=1&b=2'), { a: '1', b: '2' });
  assert.deepEqual(parseQuery('a=1&b=2'), { a: '1', b: '2' });
});

test('空串是空对象，不是 { "": "" }', () => {
  assert.deepEqual(parseQuery(''), {});
  assert.deepEqual(parseQuery('?'), {});
});

test('没有等号的键，值是空串，不是字符串 undefined', () => {
  assert.deepEqual(parseQuery('a'), { a: '' });
  assert.deepEqual(parseQuery('a&b=1'), { a: '', b: '1' });
});

test('重复的键收成数组，顺序保持', () => {
  assert.deepEqual(parseQuery('a=1&a=2'), { a: ['1', '2'] });
  assert.deepEqual(parseQuery('a=1&a=2&a=3'), { a: ['1', '2', '3'] });
});

test('键和值都要 percent-decode，+ 当空格', () => {
  assert.deepEqual(parseQuery('a%20b=1'), { 'a b': '1' });
  assert.deepEqual(parseQuery('q=%E4%B8%AD%E6%96%87'), { q: '中文' });
  assert.deepEqual(parseQuery('q=a+b'), { q: 'a b' });
});

test('值里带等号时只按第一个等号切', () => {
  assert.deepEqual(parseQuery('t=a=b'), { t: 'a=b' });
});

