/** 极简事件总线 */
export class Bus {
  constructor() {
    this.listeners = [];
  }

  on(fn) {
    this.listeners.push(fn);
    return () => this.off(fn);
  }

  off(fn) {
    const i = this.listeners.indexOf(fn);
    if (i >= 0) this.listeners.splice(i, 1);
  }

  emit(ev) {
    for (const fn of this.listeners) fn(ev);
  }
}

files.once.js:
/** 只收一次，收到就自己退订 */
export function once(bus, fn) {
  const off = bus.on((ev) => {
    off();
    fn(ev);
  });
  return off;
}

