import { once } from './once.js';

/** 挂两个「只收一次」的监听者，各自记一条 */
export function collectTwo(bus) {
  const got = [];
  once(bus, (e) => got.push(e));
  once(bus, (e) => got.push(e));
  return got;
}

files.check.test.js:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Bus } from './bus.js';
import { collectTwo } from './collect.js';

test('一次 emit 里每个监听者都要收到，即使有人在回调里退订自己', () => {
  const bus = new Bus();
  const got = collectTwo(bus);
  bus.emit('a');
  assert.deepEqual(got, ['a', 'a']);
  bus.emit('b');
  assert.deepEqual(got, ['a', 'a'], 'once 就是只收一次');
});

test('普通退订仍然生效', () => {
  const bus = new Bus();
  const seen = [];
  const off = bus.on((e) => seen.push(e));
  bus.emit(1);
  off();
  bus.emit(2);
  assert.deepEqual(seen, [1]);
});

test('emit 期间新加的监听者不参与这一轮', () => {
  const bus = new Bus();
  const seen = [];
  bus.on(() => bus.on(() => seen.push('late')));
  bus.emit('x');
  assert.deepEqual(seen, []);
  bus.emit('y');
  assert.deepEqual(seen, ['late']);
});

