/**
 * 按并发上限跑一批任务，结果按**输入顺序**返回。
 * 现在的实现是串行的：limit 被忽略了。
 */
export async function mapLimit(items, limit, worker) {
  const out = [];
  for (const item of items) out.push(await worker(item));
  return out;
}

files.check.test.js:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mapLimit } from './pool.js';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

test('结果按输入顺序，并发峰值正好是上限', async () => {
  let running = 0;
  let peak = 0;
  const items = [1, 2, 3, 4, 5, 6, 7, 8];
  const out = await mapLimit(items, 3, async (n) => {
    running += 1;
    peak = Math.max(peak, running);
    await sleep(30);
    running -= 1;
    return n * 2;
  });
  assert.deepEqual(out, [2, 4, 6, 8, 10, 12, 14, 16]);
  assert.equal(peak, 3, `并发峰值应为 3，实际 ${peak}（1 说明还是串行）`);
});

test('快的任务先完成也不能打乱结果顺序', async () => {
  const out = await mapLimit([50, 10, 30], 3, async (ms) => {
    await sleep(ms);
    return ms;
  });
  assert.deepEqual(out, [50, 10, 30]);
});

test('上限大于任务数、空输入都要正常', async () => {
  assert.deepEqual(await mapLimit([1, 2], 10, async (n) => n), [1, 2]);
  assert.deepEqual(await mapLimit([], 3, async () => 1), []);
});

test('有任务抛错时整体 reject', async () => {
  await assert.rejects(
    () =>
      mapLimit([1, 2, 3], 2, async (n) => {
        if (n === 2) throw new Error('boom');
        return n;
      }),
    /boom/,
  );
});

test('并发是真的：8 个 30ms 任务、上限 4，总耗时明显小于串行', async () => {
  const t0 = Date.now();
  await mapLimit([1, 2, 3, 4, 5, 6, 7, 8], 4, async () => sleep(30));
  const ms = Date.now() - t0;
  assert.ok(ms < 150, `应该在 150ms 内跑完（串行要 240ms+），实际 ${ms}ms`);
});

files.semver.js:
/**
 * 比较两个版本号：a < b 返回 -1，a > b 返回 1，相等返回 0。
 * 现在的实现只会按字符串比，几乎所有边界都是错的。
 */
export function compare(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

files.check.test.js:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { compare } from './semver.js';

test('主干按数字比，不是按字符串', () => {
  assert.equal(compare('1.2.10', '1.2.9'), 1);
  assert.equal(compare('1.10.0', '1.9.0'), 1);
  assert.equal(compare('2.0.0', '10.0.0'), -1);
});

test('缺的段按 0 补', () => {
  assert.equal(compare('1.2', '1.2.0'), 0);
  assert.equal(compare('1', '1.0.0'), 0);
  assert.equal(compare('1.2', '1.2.1'), -1);
});

test('前导 v 和空白要容忍', () => {
  assert.equal(compare('v1.2.3', '1.2.3'), 0);
  assert.equal(compare('  1.2.3 ', '1.2.3'), 0);
});

test('有预发布的小于同主干的正式版', () => {
  assert.equal(compare('1.2.0-alpha', '1.2.0'), -1);
  assert.equal(compare('1.2.0', '1.2.0-alpha'), 1);
});

test('预发布之间：数字段按数字比，字母段按字典序', () => {
  assert.equal(compare('1.2.0-alpha.2', '1.2.0-alpha.10'), -1);
  assert.equal(compare('1.2.0-alpha', '1.2.0-beta'), -1);
  assert.equal(compare('1.2.0-rc.1', '1.2.0-rc.1'), 0);
});

test('预发布段数不同时，段少的更小', () => {
  assert.equal(compare('1.2.0-alpha', '1.2.0-alpha.1'), -1);
});

test('数字段永远小于字母段', () => {
  assert.equal(compare('1.2.0-1', '1.2.0-alpha'), -1);
});

test('build 元数据不参与比较', () => {
  assert.equal(compare('1.2.0+build.9', '1.2.0+build.1'), 0);
  assert.equal(compare('1.2.0-alpha+x', '1.2.0-alpha+y'), 0);
});

test('能直接拿去 sort', () => {
  const sorted = ['1.2.0', '1.2.0-beta', '1.0.0', '1.2.0-alpha.2', '1.2.0-alpha.10'].sort(compare);
  assert.deepEqual(sorted, ['1.0.0', '1.2.0-alpha.2', '1.2.0-alpha.10', '1.2.0-beta', '1.2.0']);
});
